module frog_tower_finder (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] frog_x_0, frog_d_0,\n    input wire [7:0] frog_x_1, frog_d_1,\n    input wire [7:0] frog_x_2, frog_d_2,\n    input wire [7:0] frog_x_3, frog_d_3,\n    input wire [1:0] num_frogs,\n    output reg [7:0] best_position,\n    output reg [7:0] tower_size,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] GENERATE_POS = 3'd1;\n    localparam [2:0] SORT         = 3'd2;\n    localparam [2:0] COUNT        = 3'd3;\n    localparam [2:0] FINISHED     = 3'd4;\n    \n    reg [2:0] state;\n    reg [7:0] positions [0:255];\n    reg [8:0] pos_count;\n    reg [2:0] frog_idx;\n    reg [2:0] frog_gen_state;\n    reg [7:0] current_pos;\n    reg [7:0] current_d;\n    reg [7:0] next_gen;\n    reg [8:0] sort_idx;\n    reg [8:0] sort_limit;\n    reg [7:0] unsorted_temp;\n    reg [7:0] current_count;\n    reg [7:0] max_count;\n    reg [7:0] best_pos_reg;\n    reg [7:0] sorted_positions [0:255];\n    reg counting_start;\n    reg [8:0] count_idx;\n    \n    integer i;\n    \n    // Prime verification for distance\n    function valid_prime(input [7:0] d);\n        begin\n            valid_prime = (d == 8'd2) || (d == 8'd3) || (d == 8'd5) || (d == 8'd7);\n        end\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            pos_count <= 9'd0;\n            done <= 1'b0;\n            best_position <= 8'd0;\n            tower_size <= 8'd0;\n            \n            for (i = 0; i < 256; i = i + 1) begin\n                positions[i] <= 8'd0;\n                sorted_positions[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    pos_count <= 9'd0;\n                    frog_idx <= 3'd0;\n                    \n                    if (start && (num_frogs >= 2'd1) && (num_frogs <= 2'd4)) begin\n                        state <= GENERATE_POS;\n                        case (frog_idx)\n                            0: {current_pos, current_d} <= {frog_x_0, frog_d_0};\n                            1: {current_pos, current_d} <= {frog_x_1, frog_d_1};\n                            2: {current_pos, current_d} <= {frog_x_2, frog_d_2};\n                            3: {current_pos, current_d} <= {frog_x_3, frog_d_3};\n                        endcase\n                    end\n                end\n                \n                GENERATE_POS: begin\n                    if (valid_prime(current_d) && (current_pos <= 8'd255)) begin\n                        positions[pos_count] <= current_pos;\n                        pos_count <= pos_count + 9'd1;\n                        next_gen <= current_pos + current_d;\n                    end else begin\n                        frog_idx <= frog_idx + 3'd1;\n                        if (frog_idx == num_frogs) begin\n                            state <= SORT;\n                            sort_limit <= pos_count - 9'd1;\n                            sort_idx <= 9'd0;\n                        end else begin\n                            case (frog_idx + 1)\n                                0: {current_pos, current_d} <= {frog_x_0, frog_d_0};\n                                1: {current_pos, current_d} <= {frog_x_1, frog_d_1};\n                                2: {current_pos, current_d} <= {frog_x_2, frog_d_2};\n                                3: {current_pos, current_d} <= {frog_x_3, frog_d_3};\n                            endcase\n                        end\n                    end\n                    current_pos <= next_gen;\n                end\n                \n                SORT: begin\n                    if (sort_idx < sort_limit) begin\n                        if (positions[sort_idx] > positions[sort_idx + 1]) begin\n                            unsorted_temp <= positions[sort_idx];\n                            positions[sort_idx] <= positions[sort_idx + 1];\n                            positions[sort_idx + 1] <= unsorted_temp;\n                        end\n                        sort_idx <= sort_idx + 9'd1;\n                    end else begin\n                        sort_limit <= sort_limit - 9'd1;\n                        sort_idx <= 9'd0;\n                        if (sort_limit == 9'd0) begin\n                            state <= COUNT;\n                            sort_idx <= 9'd0;\n                            max_count <= 8'd0;\n                            best_pos_reg <= 8'd0;\n                        end\n                    end\n                end\n                \n                COUNT: begin\n                    if (sort_idx == 9'd0) begin\n                        current_count <= 8'd1;\n                    end else if (positions[sort_idx] == positions[sort_idx - 1]) begin\n                        current_count <= current_count + 8'd1;\n                    end else begin\n                        if (current_count > max_count) begin\n                            max_count <= current_count;\n                            best_pos_reg <= positions[sort_idx - 1];\n                        end\n                        current_count <= 8'd1;\n                    end\n                    \n                    if (sort_idx == pos_count) begin\n                        if (current_count > max_count) begin\n                            max_count <= current_count;\n                            best_pos_reg <= positions[sort_idx - 1];\n                        end\n                        tower_size <= max_count;\n                        best_position <= best_pos_reg;\n                        state <= FINISHED;\n                    end else begin\n                        sort_idx <= sort_idx + 9'd1;\n                    end\n                end\n                \n                FINISHED: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule